import React, { useState, useEffect } from "react";
import axios from "axios";
import QuestionCard from "./component/QuestionCard";
import "./App.css";

function App() {
  const [questions, setQuestions] = useState([]);
  const [hideAnswers, setHideAnswers] = useState(false);
  const [name, setName] = useState("");
  const [error, setError] = useState("");

  const createEmptyForm = () => [
    { question: "", answer: "", confirmAnswer: "" },
    { question: "", answer: "", confirmAnswer: "" },
    { question: "", answer: "", confirmAnswer: "" },
    { question: "", answer: "", confirmAnswer: "" },
    { question: "", answer: "", confirmAnswer: "" }
  ];

  const [qaList, setQaList] = useState(createEmptyForm());

  useEffect(() => {
    axios.get("http://localhost:3001/questions")
      .then((res) => setQuestions(Array.isArray(res.data) ? res.data : []))
      .catch((err) => console.error(err));
  }, []);

  const handleUpdate = (index, field, value) => {
    const updated = [...qaList];
    updated[index][field] = value;
    setQaList(updated);
  };

  const getAvailableQuestions = (currentIndex) => {
    const used = qaList
      .filter((_, idx) => idx !== currentIndex)
      .map(item => item.question);

    return questions.filter(q => !used.includes(q.question));
  };

  const handleSubmit = async () => {
    setError("");

    if (!name.trim()) {
      return setError("Name is required");
    }

    const isComplete = qaList.every(q => q.question && q.answer && q.confirmAnswer);
    if (!isComplete) {
      return setError("Please fill all fields");
    }

    const isMatched = qaList.every(q => q.answer === q.confirmAnswer);
    if (!isMatched) {
      return setError("Answers do not match");
    }

    const responses = qaList.map(q => {
      const selected = questions.find(item => item.question === q.question);

      return {
        q_id: selected?.q_id,
        question: q.question,
        answer: q.answer
      };
    });

    try {
      await axios.post("http://localhost:3001/responses", {
        name,
        responses
      });

      alert("Submitted Successfully!");
      setQaList(createEmptyForm());
      setName("");

    } catch (err) {
      setError("Error saving data");
    }
  };

  return (
    <div className="app-container">
      <h1>Security Form</h1>

      <input
        type="text"
        placeholder="Enter your name"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />

      {error && <p style={{ color: "red" }}>{error}</p>}

      {qaList.map((qa, i) => (
        <QuestionCard
          key={i}
          index={i}
          qa={qa}
          questions={getAvailableQuestions(i)}
          hideAnswers={hideAnswers}
          onChange={handleUpdate}
        />
      ))}

      <label>
        <input
          type="checkbox"
          checked={hideAnswers}
          onChange={() => setHideAnswers(!hideAnswers)}
        />
        Hide Answers
      </label>

      <button onClick={handleSubmit}>Submit</button>
    </div>
  );
}

export default App;
